import {analysisDeadline,modelBudget} from './analysis-deadline.js?v=20261027motion';
import{reviewThumbnail}from './frame-review.js?v=20261027motion';
import{filterReviewFrames,pageReviewFrames}from './frame-review-core.js?v=20261027motion';
import{groupRectangularWindows,groupCircleWindows}from './window-shapes.js?v=20261027motion';
import {referenceAudioTask} from './breakdown.js?v=20261028wipe';
import {followEvidence,trackingCoverage} from './spatial-core.js?v=20261027motion';
const $=id=>document.getElementById(id);let worker=null,pending=new Map(),seq=0,controller=null,textData=null,latest=null;
const abort=()=>{controller?.abort();worker?.terminate();worker=null;for(const p of pending.values())p.reject(Error('空间分析已停止'));pending.clear()};
function rpc(type,data={}){return new Promise((resolve,reject)=>{const id=++seq,timer=setTimeout(()=>{pending.delete(id);reject(Error('空间分析超时，请缩短视频后重试'))},120000);pending.set(id,{resolve:v=>{clearTimeout(timer);resolve(v)},reject:e=>{clearTimeout(timer);reject(e)}});worker.postMessage({id,type,...data})})}
function startWorker(){worker=new Worker(new URL('./spatial-worker.js?v=20261027motion',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress'){$('spatial-status').textContent=data.text;return}const p=pending.get(data.id);pending.delete(data.id);if(!p)return;data.type==='error'?p.reject(Error(data.text)):p.resolve(data.result)};worker.onerror=()=>{for(const p of pending.values())p.reject(Error('空间分析引擎运行失败'));pending.clear()};}

function event(video,name,signal){return new Promise((resolve,reject)=>{const clean=()=>{clearTimeout(timer);video.removeEventListener(name,done);video.removeEventListener('error',fail);signal.removeEventListener('abort',cancel)},done=()=>{clean();resolve()},fail=()=>{clean();reject(Error('视频解码失败'))},cancel=()=>{clean();reject(Error('空间分析已停止'))},timer=setTimeout(()=>{clean();reject(Error('视频解码超时'))},15000);video.addEventListener(name,done,{once:true});video.addEventListener('error',fail,{once:true});signal.addEventListener('abort',cancel,{once:true});if(signal.aborted)cancel()})}
function maskImage(mask,width=mask.width,height=mask.height){const canvas=document.createElement('canvas');canvas.width=mask.width;canvas.height=mask.height;const ctx=canvas.getContext('2d'),img=ctx.createImageData(mask.width,mask.height);for(let i=0;i<mask.pixels.length;i++){img.data[i*4]=img.data[i*4+1]=img.data[i*4+2]=mask.pixels[i];img.data[i*4+3]=255}ctx.putImageData(img,0,0);const output=document.createElement('canvas');output.width=width;output.height=height;output.getContext('2d').drawImage(canvas,0,0,width,height);return output.toDataURL('image/png')}
function update(){if(!latest)return;latest.following=followEvidence(textData?.tracks||[],latest.features);document.dispatchEvent(new CustomEvent('spatial-evidence-result',{detail:latest}));render(latest)}
function render(data,selftest=false){const box=$('spatial-results');box.replaceChildren();const p=document.createElement('p');p.textContent=`${selftest?'Google 官方公开肖像图片自检（不是上传视频结果） · ':''}连续采样 ${data.frames.length} 帧；${data.frames.filter(f=>f.person).length} 帧获得人物分割，${data.circles.length} 组圆形窗口线索，${(data.rectangles||[]).length} 组矩形动态窗口线索，${data.following.length} 组文字与目标同动线索。分割人物不是原片使用过抠像的证明。`;box.append(p);if(!selftest){const coverage=trackingCoverage(data.frames,data.features),note=document.createElement('p');note.className='muted';note.textContent=coverage.intervals.length?`可靠局部轨迹区间：${coverage.intervals.map(i=>i.start.toFixed(2)+'–'+i.end.toFixed(2)+' 秒').join('；')}。已检查双向匹配；没有轨迹的时间段不代表没有跟踪效果。`:'未得到连续四帧的可靠局部轨迹，不能判断本片没有跟踪效果。';box.append(note)}const gallery=document.createElement('div'),toolbar=document.createElement('div'),filterLabel=document.createElement('label'),filter=document.createElement('select'),grid=document.createElement('div'),navigation=document.createElement('div');toolbar.className=navigation.className='review-controls';filterLabel.textContent='采样范围 ';for(const[value,title]of [['all','全部采样帧'],['geometry','仅边界线索'],['people','仅可靠人物']])filter.add(new Option(title,value));filterLabel.append(filter);toolbar.append(filterLabel);const hint=document.createElement('p');hint.className='muted';hint.textContent='点击图片放大、隐藏测量标记或暂停定位原片。单帧边界尚不等于已通过连续变化检查的蒙版候选。';gallery.append(toolbar,hint,grid,navigation);grid.className='text-sample-grid';let page=0;function drawPage(){const filtered=filterReviewFrames(data.frames,filter.value),view=pageReviewFrames(filtered,page);page=view.page;grid.replaceChildren();for(let i=0;i<view.frames.length;i++){const f=view.frames[i],figure=document.createElement('figure'),caption=document.createElement('figcaption');figure.append(reviewThumbnail(filtered,view.start+i,{allowSeek:!selftest}));caption.textContent=`${f.time.toFixed(2)} 秒 · ${f.person?'可靠人物；':''}${f.circles?.length?'单帧圆形 '+f.circles.length+' 个；':''}${f.rectangles?.length?'单帧矩形 '+f.rectangles.length+' 个':''}${!f.person&&!f.circles?.length&&!f.rectangles?.length?'本帧未提取可靠空间线索':''}`;figure.append(caption);if(f.maskImage){const a=document.createElement('a');a.href=f.maskImage;a.download=`ClipPilot-人物遮罩-${f.time.toFixed(2)}s.png`;a.textContent='下载本帧新计算的人物遮罩';figure.append(a)}grid.append(figure)}navigation.replaceChildren();const prev=document.createElement('button'),next=document.createElement('button'),count=document.createElement('span');prev.className=next.className='secondary';prev.textContent='上一页采样';next.textContent='下一页采样';prev.disabled=page===0;next.disabled=page>=view.pages-1;count.textContent=`第 ${page+1} / ${view.pages} 页 · 共 ${view.total} 帧`;prev.onclick=()=>{page--;drawPage()};next.onclick=()=>{page++;drawPage()};navigation.append(prev,count,next);if(!view.total){const empty=document.createElement('p');empty.textContent='当前筛选没有采样帧；没有线索不代表没有效果。';grid.append(empty)}}filter.onchange=()=>{page=0;drawPage()};drawPage();box.append(gallery);for(const follow of data.following){const wrapper=document.createElement('div');wrapper.className='motion-evidence';const label=document.createElement('p');label.textContent=`${follow.start.toFixed(2)}–${follow.end.toFixed(2)} 秒 · “${follow.text}”与局部目标的实测轨迹。蓝线是目标，橙线是文字；同动不证明自动跟踪。`;wrapper.append(label);const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('preserveAspectRatio','none');svg.setAttribute('aria-label','文字和目标的归一化运动轨迹');for(const [key,color]of [['target','#1647df'],['text','#de7318']]){const line=document.createElementNS(ns,'polyline');line.setAttribute('points',follow.path.map(p=>`${p[key].x*100},${p[key].y*100}`).join(' '));line.setAttribute('stroke',color);line.setAttribute('stroke-width','1.3');line.setAttribute('fill','none');svg.append(line)}wrapper.append(svg);box.append(wrapper)}if(!textData){const p=document.createElement('p');p.textContent='跟随关系需要画面文字轨迹。运行“识别画面文字”后，会自动与已有运动轨迹交叉检查。';box.append(p)}}
async function run(){controller=new AbortController();const signal=controller.signal,budget=modelBudget($('analysis-budget').value),deadline=analysisDeadline(budget,abort);try{$('spatial-stop').hidden=false;$('spatial-status').textContent='准备重新采样连续画面…';latest=await referenceAudioTask(async({file,reference})=>{startWorker();await rpc('load');const url=URL.createObjectURL(file),video=document.createElement('video'),canvas=document.createElement('canvas');video.muted=true;video.playsInline=true;canvas.width=240;canvas.height=Math.max(32,Math.round(240*reference.height/reference.width));if(canvas.height>320){canvas.height=320;canvas.width=Math.round(320*reference.width/reference.height)}const detailCanvas=document.createElement('canvas');detailCanvas.width=Math.min(960,reference.width);detailCanvas.height=Math.round(detailCanvas.width*reference.height/reference.width);if(detailCanvas.height>960){detailCanvas.height=960;detailCanvas.width=Math.round(960*reference.width/reference.height)}const detailCtx=detailCanvas.getContext('2d');const ctx=canvas.getContext('2d',{willReadFrequently:true}),frames=[],raw=[],count=Math.min(90,Math.max(4,Math.ceil(reference.duration*2)));try{const ready=event(video,'loadeddata',signal);video.src=url;video.load();await ready;for(let i=0;i<count;i++){if(signal.aborted)throw Error('空间分析已停止');const time=(i+.5)*reference.duration/count,ready=event(video,'seeked',signal);video.currentTime=time;await ready;ctx.drawImage(video,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data,rgb=new Uint8Array(canvas.width*canvas.height*3);for(let j=0,k=0;j<pixels.length;j+=4){rgb[k++]=pixels[j];rgb[k++]=pixels[j+1];rgb[k++]=pixels[j+2]}const frame={time,width:canvas.width,height:canvas.height,pixels:rgb};$('spatial-status').textContent=`检查边界与人物主体 ${i+1}/${count} · ${time.toFixed(2)} 秒`;detailCtx.drawImage(video,0,0,detailCanvas.width,detailCanvas.height);const originalImage=detailCanvas.toDataURL('image/jpeg',.82);const result=await rpc('frame',{frame});frames.push({...result,originalImage,sampleWidth:canvas.width,sampleHeight:canvas.height,maskImage:result.mask?maskImage(result.mask,canvas.width,canvas.height):null,image:canvas.toDataURL('image/jpeg',.75)});delete frames.at(-1).mask;raw.push(frame)}const features=await rpc('track',{frames:raw});return{reference,frames,features,circles:groupCircleWindows(frames,reference.duration/count*1.6),rectangles:groupRectangularWindows(frames,reference.duration/count*1.6),following:[]}}finally{video.pause();video.removeAttribute('src');video.load();URL.revokeObjectURL(url)}},{stopId:'spatial-stop',taskName:'分析蒙版、主体与跟随线索'});update();$('spatial-status').textContent='空间分析完成。下方展示真实采样、人物遮罩和运动测量；剪映步骤已加入整片清单与检测教学。原工程使用了何种蒙版、抠像或跟踪功能仍不能直接证明。';return true}catch(e){$('spatial-status').textContent=deadline.expired?`空间检查达到 ${budget/1000} 秒时限，未提交不完整结果。已完成结果保留；可选较长时限后重试。`:'空间分析未完成：'+e.message;return false}finally{deadline.close();worker?.terminate();worker=null;controller=null;$('spatial-stop').hidden=true}}
$('spatial-start').onclick=run;$('spatial-stop').onclick=abort;document.addEventListener('text-evidence-result',e=>{textData=e.detail;update()});document.addEventListener('reference-changed',()=>{textData=null;latest=null;$('spatial-results').replaceChildren();$('spatial-status').textContent='视频已更换，尚未分析空间线索。'});

$('spatial-selftest').onclick=async()=>{controller=new AbortController();const signal=controller.signal;try{$('spatial-stop').hidden=false;$('spatial-status').textContent='读取官方公开人物图片，运行独立分割自检…';const data=await referenceAudioTask(async()=>{startWorker();await rpc('load');const response=await fetch('https://storage.googleapis.com/mediapipe-assets/portrait.jpg',{signal});if(!response.ok)throw Error('官方人物示例读取失败');const bitmap=await createImageBitmap(await response.blob()),canvas=document.createElement('canvas');canvas.width=240;canvas.height=Math.round(240*bitmap.height/bitmap.width);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const rgba=ctx.getImageData(0,0,canvas.width,canvas.height).data,pixels=new Uint8Array(canvas.width*canvas.height*3);for(let i=0,j=0;i<rgba.length;i+=4){pixels[j++]=rgba[i];pixels[j++]=rgba[i+1];pixels[j++]=rgba[i+2]}const result=await rpc('frame',{frame:{width:canvas.width,height:canvas.height,pixels,time:0}});return{frames:[{...result,maskImage:result.mask?maskImage(result.mask,canvas.width,canvas.height):null,image:canvas.toDataURL('image/jpeg',.8)}],circles:[],features:[],following:[]}},{example:true,stopId:'spatial-stop',taskName:'人物分割模型自检'});render(data,true);$('spatial-status').textContent=data.frames[0].person?'官方人物图片自检完成：已生成实际前景遮罩。这里只验证人物分割能运行，不证明任意视频抠像准确，也不判断原片是否做过抠像。':'官方人物图片自检未获得可靠前景，不能视为通过。'}catch(e){$('spatial-status').textContent='人物自检未完成：'+e.message}finally{worker?.terminate();worker=null;controller=null;$('spatial-stop').hidden=true}};
